SELECT
t_skill.*,
t_skill_version.obs_path,
t_skill_version.version_name
FROM
t_skill
LEFT JOIN
t_skill_version ON t_skill.latest_version = t_skill_version.id


        AND domain_id = #{skill.domainId, jdbcType=VARCHAR}


        AND t_skill.name LIKE CONCAT('%', #{skill.name, jdbcType=VARCHAR}, '%') ESCAPE '!'


        AND t_skill.description LIKE CONCAT('%', #{skill.description, jdbcType=VARCHAR}, '%') ESCAPE '!'


        AND status = #{skill.status, jdbcType=VARCHAR}


        AND source = #{skill.source, jdbcType=VARCHAR}


        AND workspace_id = #{skill.workspaceId, jdbcType=VARCHAR}


        AND project_id = #{skill.projectId, jdbcType=VARCHAR}


        AND tag_id = #{tagId, jdbcType=VARCHAR}


        AND published_asset = CONCAT(#{publishedAsset}, '')


ORDER BY


        (t_skill.status = #{priorityStatus, jdbcType=VARCHAR}) DESC,
        t_skill.created_at DESC


        t_skill.created_at DESC


LIMIT #{limit, jdbcType=INTEGER} OFFSET #{offset, jdbcType=INTEGER}

SELECT
COUNT(*)
FROM
t_skill
LEFT JOIN
t_skill_version ON t_skill.latest_version = t_skill_version.id


        AND domain_id = #{domainId, jdbcType=VARCHAR}


        AND t_skill.name LIKE CONCAT('%', #{name, jdbcType=VARCHAR}, '%') ESCAPE '!'


        AND t_skill.description LIKE CONCAT('%', #{description, jdbcType=VARCHAR}, '%') ESCAPE '!'


        AND status = #{status, jdbcType=VARCHAR}


        AND source = #{source, jdbcType=VARCHAR}


        AND workspace_id = #{workspaceId, jdbcType=VARCHAR}


        AND project_id = #{projectId, jdbcType=VARCHAR}


        AND published_asset = CONCAT(#{publishedAsset}, '')
